const ACAD={"N.T. Wright": {"2": {"c": 1, "n": "Revelation for Everyone (2011) reads the book against the church's first-century conflict with Rome and treats its symbols as lasting truths; reviewers class it as preterist with idealist elements.", "s": [["Collected Miscellany: review of Revelation for Everyone (2011)", "https://www.collectedmiscellany.com/?p=8718"], ["Review of Revelation for Everyone (2012)", "https://www.goodreads.com/author_blog_posts/1970811-non-fiction-review-revelation-for-everyone-by-n-t-wright"]]}, "6": {"c": 1, "n": "Latest known: on the Unbelievable podcast he said the finally impenitent person 'simply ceases ultimately to exist'; 'you are no longer an image bearer'; annihilationism 'has something going for it'. Earlier (Surprised by Hope, 2008) he described them living on as beings who have 'ceased to bear the divine image', 'beyond pity'. Not a universalist.", "s": [["Protestia: N.T. Wright on annihilationism (quotes the Unbelievable podcast)", "https://protestia.substack.com/p/nt-wright-defends-annihilationism"], ["Surprised by Hope on hell (2008, blog summary)", "https://oneinjesus.info/2008/07/surprised-by-hope-hell-part-1/"]]}}, "Darrell Bock": {"8": {"c": 0, "n": "Redemption includes the created order: redeemed Jewish and Gentile nations live on in the new creation (his chapter in Covenantal and Dispensational Theologies: Four Views, 2022).", "s": [["Exegesis and Theology: Bock's chapter in Covenantal and Dispensational Theologies (2022)", "https://exegesisandtheology.com/2022/11/30/darrell-bock-progressive-dispensationalism-in-covenantal-and-dispensational-theologies-four-views-agreements-and-disagreements/"]]}}, "J.I. Packer": {"13": {"c": 1, "n": "Concise Theology (1993), 'Perseverance: God Keeps His People Safe': the regenerate 'can neither totally nor finally fall from the state of grace' (quoting Westminster); not all who profess conversion will be saved.", "s": [["Monergism: Packer, Perseverance (Concise Theology)", "https://www.monergism.com/thethreshold/articles/onsite/packer/perseverance.html"], ["J.I. Packer on the perseverance of the saints (2007)", "https://chedspellman.com/2007/02/ji-packer-on-perseverance-of-saints.html"]]}}};
